div.div:
📢 Campaign Service
Endpoints:
GET | POST /v1/campaigns
GET | PUT /v1/campaigns/{id}
...
Setup:
build.gradle →
spring-boot-starter-security
spring-boot-starter-oauth2-resource-server
application.yml →
spring.security.oauth2.resourceserver.jwt.issuer-uri=https://domain.okta.com
@Configuration @EnableWebSecurity @EnableMethodSecurity
SecurityConfig.java →
.requestMatchers('/v1/campaigns/**').authenticated()
converter.setAuthorityPrefix('SCOPE_')
@RequestMapping('/v1/campaigns')
CampaignController.java →
@GetMapping
@PreAuthorize('hasAuthority(SCOPE_campaigns:read)')
List<Campaign> getAllCampaigns()
@GetMapping('/{id}')
@PreAuthorize('hasAuthority(SCOPE_campaigns:read)')
Campaign getCampaignById()
@PostMapping
@PreAuthorize('hasAuthority(SCOPE_campaigns:write)')
Campaign createCampaign()
@PutMapping('/{id}')
@PreAuthorize('hasAuthority(SCOPE_campaigns:write)')
Campaign updateCampaign(@PathVariable String id, @RequestBody Campaign request)
